            EditorGUILayout.HelpBox(
                $"房间宽高必须为 {wallTileSize} 的整数倍！当前: {roomTilesX}×{roomTilesY}", MessageType.Error);
        else
            EditorGUILayout.HelpBox(
                $"每面墙块数: {roomTilesX / wallTileSize}×{roomTilesY / wallTileSize} = " +
